<?php declare(strict_types=1); namespace Annam; $title='Store settings'; ?>
<form class="o-form" method="post" enctype="multipart/form-data"><?= csrf() ?><section class="o-card"><h2>Your store</h2><div class="o-grid-form"><?php foreach(['brand_name'=>'Store name','tagline'=>'Tagline','support_phone'=>'Phone / WhatsApp'] as $key=>$label): ?><label class="o-field"><span><?= e($label) ?></span><input name="<?= e($key) ?>" value="<?= e($store->config[$key]) ?>"></label><?php endforeach; ?><label class="o-field">Email<input type="email" name="contact_email" value="<?= e($website->copy['footer.email']) ?>"></label><label class="o-field">Brand colour<input type="color" name="brand_color" value="<?= e($store->config['theme']['brand']??'#FF8507') ?>"></label><label class="o-field">Logo<img src="<?= e($store->logo()) ?>" alt="Current logo" width="120"><input type="file" name="logo" accept="image/jpeg,image/png,image/webp"></label><label class="o-field">Public contact address<textarea name="footer_address"><?= e($website->copy['footer.address']) ?></textarea></label><label class="o-field">Announcements (one per line)<textarea name="announcements"><?= e(implode("\n",$store->config['theme']['announcements']??[])) ?></textarea></label></div></section><section class="o-card"><h2>Website introduction</h2><?php foreach(['kicker'=>'Small heading','title'=>'Headline','body'=>'Introduction'] as $key=>$label): ?><label class="o-field"><?= e($label) ?><textarea name="hero_<?= e($key) ?>"><?= e($website->copy['hero.'.$key]) ?></textarea></label><?php endforeach; ?></section><section class="o-card"><h2>Ordering</h2><?php foreach(['website_ordering'=>'Take orders on the website','snacks_courier'=>'Enable the shop','manual_payments'=>'Allow manual payment arrangements','cod'=>'Allow cash on delivery'] as $key=>$label): ?><label class="php-switch-row"><input class="php-toggle" role="switch" type="checkbox" name="<?= e($key) ?>" value="1" <?= ($store->config['features'][$key]??in_array($key,['website_ordering','manual_payments']))?'checked':'' ?>><span><?= e($label) ?></span><b class="php-switch-state" aria-hidden="true"></b></label><?php endforeach; ?></section><button class="o-btn o-btn-primary">Save settings</button></form><section class="o-card"><h2>Photo backup</h2><p>Download referenced photos and a missing-file report. Database backups and private encryption keys must be backed up separately.</p><form method="post" action="/manage/settings/media-backup/"><?= csrf() ?><button class="o-btn">Download media ZIP</button></form></section>
